import { hash01 } from "./hash.js";

/**
 * Погода заезда из посева: солнце не ниже двадцати и не выше шестидесяти
 * градусов (ниже — дорога тонет в контрасте, выше — исчезают тени и с ними
 * объём), сторона любая, мутность от прозрачного дня до летнего пекла,
 * облачность от редких клочков до сплошной пелены, ветер от слабого до свежего.
 *
 * Погода — это то, что общее у всех, кто в мире находится, и потому она лежит
 * здесь, а не внутри неба, где лежала раньше. Пока ветер был полем небесного
 * модуля, лес получал его через сцену, которая доставала его из неба: связь
 * между «дует» и «качается» шла через третьего, и добавить к ней машину (пыль
 * сносит ветром) было некуда.
 */
export interface Weather {
  /** Высота солнца над горизонтом, радианы. */
  elevation: number;
  /** Сторона света, радианы. */
  azimuth: number;
  /** Мутность воздуха: от прозрачного дня до летнего пекла. */
  turbidity: number;
  /** Доля закрытого облаками неба. */
  cover: number;
  /** Сила ветра: 0 — штиль, 1 — свежий. */
  wind: number;
  /** Куда дует, радианы: тот же отсчёт, что у стороны света. */
  windRad: number;
}

export function weatherFor(seed: number): Weather {
  return {
    elevation: (25 + hash01(seed, 0, 91) * 34) * (Math.PI / 180),
    azimuth: hash01(seed, 0, 92) * Math.PI * 2,
    turbidity: 2 + hash01(seed, 0, 93) * 8,
    // Небо не должно затягивать: за облаками пропадает и солнце, и с ним весь
    // объём сцены. Половина неба открытой — верхняя граница, а не середина вилки.
    cover: 0.1 + hash01(seed, 0, 94) * 0.32,
    // Полного штиля не бывает: неподвижный лес выглядит нарисованным.
    wind: 0.45 + hash01(seed, 0, 95) * 0.75,
    windRad: hash01(seed, 0, 96) * Math.PI * 2,
  };
}
